import {html,render as baseRender,noChange,css} from "lit";
import {AsyncDirective,directive,PartType} from "lit/async-directive.js";
import {createStore,batch} from "@tanstack/lit-store";
import {Capturing} from "./dist/base.js";
import {atomState} from "./dist/shared/atom-state.js";
const creationScope={importNode(node,deep){return "customElementRegistry" in Element.prototype ? document.importNode(node,{selfOnly:!deep,customElementRegistry:customElements}) : document.importNode(node,deep);}};
const render=(v,container)=>baseRender(v,container,{creationScope});
const results=[];const check=(name,actual,expected)=>results.push({name,actual,expected,pass:JSON.stringify(actual)===JSON.stringify(expected)});
class Owned extends Capturing {
 static styles=css`#content {padding:24px;padding-inline:4px;background-color:transparent}`;
 static get observedAttributes(){return [...super.observedAttributes,"background-color"];}
 attributeChangedCallback(name,old,value){if(name==="background-color"){this.backgroundColor=value??undefined;return;}super.attributeChangedCallback(name,old,value);}
 applyInputs(values,previousKeys=[],batched=true){
  const touched=new Set([...previousKeys,...Object.keys(values)]),unmanaged=this.declarationOrder.filter(k=>!touched.has(k));
  const write=()=>{for(const key of previousKeys)if(!Object.hasOwn(values,key))this[key]=undefined;for(const key of Object.keys(values))this[key]=values[key];this.declarationOrder=[...unmanaged,...Object.keys(values).filter(k=>values[k]!==undefined)];};
  if(batched)batch(write);else write();
 }
}
atomState()(Owned.prototype,"backgroundColor");
const desc=Object.getOwnPropertyDescriptor(Owned.prototype,"backgroundColor");
Object.defineProperty(Owned.prototype,"backgroundColor",{...desc,set(value){this.record("backgroundColor",value);desc.set.call(this,value);}});
customElements.define("owned-style-probe",Owned);
class Inputs extends AsyncDirective {
 constructor(info){super(info);if(info.type!==PartType.ELEMENT)throw Error("Element expression required");}
 element;values={};generation=0;previousKeys=[];
 render(){return noChange;}
 update(part,[values]){this.element=part.element;this.values={...values};this.schedule(true);return noChange;}
 schedule(explicitUpdate=false){
  const generation=++this.generation;
  const registry=this.element.ownerDocument.defaultView.customElements;
  if(registry.get(this.element.localName)){if(explicitUpdate||this.isConnected)this.apply(generation,explicitUpdate);return;}
  if(!this.isConnected)return;
  const weak=new WeakRef(this);
  registry.whenDefined(this.element.localName).then(()=>weak.deref()?.apply(generation,false));
 }
 apply(generation,explicitUpdate){
  if(generation!==this.generation||(!explicitUpdate&&!this.isConnected))return;
  const registry=this.element.ownerDocument.defaultView.customElements;registry.upgrade(this.element);
  const previousKeys=this.previousKeys;this.previousKeys=Object.keys(this.values);this.element.applyInputs(this.values,previousKeys);
 }
 disconnected(){this.generation++;}
 reconnected(){this.schedule();}
}
const inputs=directive(Inputs);

const box=()=>{const e=document.createElement("div");document.body.append(e);return e;};
const output=e=>{const s=getComputedStyle(e.shadowRoot.querySelector("#content"));return{padding:[s.paddingTop,s.paddingRight,s.paddingBottom,s.paddingLeft],background:s.backgroundColor};};
try{
 const root=box();const draw=values=>render(html`<owned-style-probe background-color="red" title="Unrelated" ${inputs(values)}></owned-style-probe>`,root);
 draw({padding:"16px",paddingInline:"8px"});const e=root.firstElementChild;await e.updateComplete;
 check("initial helper leaves unrelated canonical input",e.backgroundColor,"red");
 check("initial helper leaves unrelated source attribute",e.getAttribute("background-color"),"red");
 check("initial helper leaves unrelated native attribute",e.title,"Unrelated");
 check("initial helper output",output(e),{padding:["16px","8px","16px","8px"],background:"rgb(255, 0, 0)"});
 const observed=[];const derived=createStore(()=>JSON.stringify([e.padding,e.paddingInline,e.backgroundColor,e.declarationOrder]));const sub=derived.subscribe(v=>observed.push(JSON.parse(v)));
 observed.length=0;draw({padding:"20px",paddingInline:"4px"});
 check("grouped write updates canonical state synchronously",[e.padding,e.paddingInline],["20px","4px"]);
 check("batched subscriber sees one complete update",observed,[["20px","4px","red",["backgroundColor","padding","paddingInline"]]]);
 await e.updateComplete;
 observed.length=0;e.applyInputs({padding:"40px",paddingInline:"9px"},["padding","paddingInline"],false);
 check("unbatched control exposes intermediate values",observed.some(x=>x[0]==="40px"&&x[1]==="4px"),true);
 observed.length=0;draw({padding:"20px",paddingInline:"4px"});await e.updateComplete;
 check("prototype reasserts inputs on next helper render",[e.padding,e.paddingInline],["20px","4px"]);
 draw({paddingInline:"6px"});await e.updateComplete;
 check("removing previously owned key clears it",e.padding===undefined,true);
 check("removed broad input exposes default while unrelated stays",output(e),{padding:["24px","6px","24px","6px"],background:"rgb(255, 0, 0)"});
 e.backgroundColor="blue";draw({paddingInline:"7px"});await e.updateComplete;
 check("subsequent helper update preserves unrelated direct write",e.backgroundColor,"blue");
 check("subsequent helper computed background stays blue",output(e).background,"rgb(0, 0, 255)");
 draw({});await e.updateComplete;
 check("empty set clears formerly owned properties",e.padding===undefined&&e.paddingInline===undefined,true);
 check("empty set leaves unrelated property",e.backgroundColor,"blue");
 draw({backgroundColor:"green",padding:"12px"});await e.updateComplete;
 check("helper can acquire a newly supplied setting",e.backgroundColor,"green");
 draw({padding:"12px"});await e.updateComplete;
 check("removing acquired setting clears it instead of restoring old value",e.backgroundColor===undefined,true);
 check("cleared acquired setting exposes CSS default",output(e).background,"rgba(0, 0, 0, 0)");
 draw({paddingInline:"3px",padding:"14px"});await e.updateComplete;
 check("owned order still applies",output(e).padding,["14px","14px","14px","14px"]);
 check("helper updates preserve element identity",root.firstElementChild===e,true);
 sub.unsubscribe();
 window.__ownershipProbe={done:true,results,passed:results.filter(x=>x.pass).length,total:results.length};
}catch(error){window.__ownershipProbe={done:true,error:String(error),stack:error.stack,results};}

